import os, json, math, sys
import numpy as np

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
M_sun = 1.98847e30      # kg

# Helper: load GWTC catalog if environment variable present
def load_catalog():
    path = os.getenv('GWTC_CATALOG_PATH')
    if not path or not os.path.isfile(path):
        print('GWTC_CATALOG_PATH not set or file does not exist; skipping catalog load.', file=sys.stderr)
        return None
    try:
        with open(path, 'r') as f:
            return json.load(f)
    except Exception as e:
        print(f'Failed to load GWTC catalog: {e}', file=sys.stderr)
        return None

def main():
    catalog = load_catalog()
    if not catalog:
        print('Skipping catalog processing – run without it by removing GWTC_CATALOG_PATH.', file=sys.stderr)
        sys.exit(0)

    events = catalog.get('events', [])
    if not events:
        print('No events found in catalog.', file=sys.stderr)
        sys.exit(0)

    failures = []
    for ev in events:
        m1 = ev.get('mass_1_source')
        m2 = ev.get('mass_2_source')
        mf = ev.get('final_mass_source')
        chi_eff = ev.get('chi_eff')
        if None in (m1, m2, mf, chi_eff):
            continue
        # Simple sanity check: ensure masses are positive and chi_eff is between -1 and 1
        if m1 <= 0 or m2 <= 0 or mf <= 0:
            continue
        if not (-1.0 <= chi_eff <= 1.0):
            continue
        # Compute radiated mass fraction (dimensionless)
        radiated_fraction = (m1 + m2 - mf) / (m1 + m2)
        # Ensure it is non‑negative
        if radiated_fraction < 0:
            radiated_fraction = 0.0
        # Simple pass/fail criterion – radiated fraction must be <= 10% for the hypothesis
        if radiated_fraction > 0.10:
            failures.append({
                'event': ev.get('event'),
                'radiated_fraction': radiated_fraction,
                'm1': m1,
                'm2': m2,
                'mf': mf,
                'chi_eff': chi_eff
            })

    if not failures:
        print('All events satisfy radiated fraction <= 0.10.')
    else:
        print('Events exceeding the threshold:')
        for f in failures:
            print(f)

if __name__ == '__main__':
    main()

