import os, json, math, sys
import numpy as np
import h5py

# Physical constants
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
M_sun = 1.98847e30      # kg

def load_gwtc_catalog():
    path = os.getenv('GWTC_CATALOG_PATH')
    if not path:
        sys.exit('Environment variable GWTC_CATALOG_PATH not set')
    with open(path, 'r') as f:
        catalog = json.load(f)
    events = catalog.get('events', [])
    filtered = []
    for ev in events:
        m1 = ev.get('mass_1_source')
        m2 = ev.get('mass_2_source')
        mf = ev.get('final_mass_source')
        if None in (m1, m2, mf):
            continue
        filtered.append((ev.get('event', 'unknown'), m1, m2, mf))
    return filtered

def chirp_mass(m1, m2):
    return (m1 * m2) ** (3/5) / (m1 + m2) ** (1/5)

def radiated_fraction(m1, m2, mf):
    return (m1 + m2 - mf) / (m1 + m2)

def main():
    events = load_gwtc_catalog()
    results = []
    total = len(events)
    if total == 0:
        print('No events found in catalog')
        sys.exit(0)
    for name, m1, m2, mf in events:
        fc = chirp_mass(m1, m2)
        rf = radiated_fraction(m1, m2, mf)
        results.append((name, fc, rf))
    # Header
    print(f"{'Event':<20} {'Chirp Mass (M_sun)':>15} {'Radiated Fraction':>15}")
    print('-' * 70)
    for name, fc, rf in results:
        print(f"{name:<20} {fc:15.6f} {rf:15.6f}")

if __name__ == '__main__':
    main()

