import numpy as np, math, sys

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
M_sun = 1.98847e30      # kg
hbar = 1.054571817e-34  # J s
k_B = 1.380649e-23      # J K^-1

def schwarzschild_radius(M):
    return 2 * G * M / c**2

def isco_radius(M):
    # Prograde ISCO radius for a non-rotating BH (a=0) from Bardeen et al. 1972
    return 6 * G * M / c**2

def horizon_area(r_s):
    return 4 * math.pi * r_s**2

def hawking_temperature(M):
    return hbar * c**3 / (8 * math.pi * G * M * k_B)

def planck_length():
    return math.sqrt(hbar * G / c**3)

def bh_entropy(M):
    r_s = schwarzschild_radius(M)
    A = horizon_area(r_s)
    l_p2 = planck_length()**2
    return A / (4 * l_p2)

def bh_entropy_dimensionless(M):
    # k_B cancels out of the entropy expression
    return bh_entropy(M) * k_B / (k_B)  # simply return the dimensionful result

def main():
    # Example: entropy of a 10 solar‑mass Schwarzschild black hole
    M = 10 * M_sun
    S = bh_entropy(M)
    print(f"Entropy of a {M/ M_sun:.1f} M_sun Schwarzschild black hole: {S:.3e} J/K")

if __name__ == "__main__":
    main()

